export function getRandomWord(lang = 'es', length = 5) {
  if (lang === 'en' && length !== 5) {
     const lists = {
      4: WORDS_4,
      6: WORDS_6,
      7: WORDS_7,
      8: WORDS_8,
      9: WORDS_9,
      10: WORDS_10,
      11: WORDS_11
    };
    const list = lists[length] || ALL_WORDS_ES;
    return list[Math.floor(Math.random() * list.length)].toLowerCase();
  }
  const words = getAllWords(lang);
  return words[Math.floor(Math.random() * words.length)].toLowerCase();
}

const ALL_WORDS_ES_SET = new Set(ALL_WORDS_ES.map(w => w.toUpperCase()));

export function isValidWord(word, lang = 'es') {
  if (!word) return false;
  return ALL_WORDS_ES_SET.has(word.toUpperCase());
}

const LANG_API_MAP = {
  'en': 'en',
  'uk': 'en',
  'es': 'es'
};

export async function validateWordOnline(word, lang = 'es') {
  const cleanWord = word.toLowerCase();
  const upperWord = word.toUpperCase();
  
  // 1. Check banned list first
  if (BANNED_SET.has(cleanWord)) {
    return { valid: false, reason: 'banned' };
  }

  // 2. Check local dictionary (Instant O(1))
  if (ALL_WORDS_ES_SET.has(upperWord)) {
    return { valid: true, reason: 'local' };
  }

  // Check the supplementary English word lists for en/uk
  if ((lang === 'en' || lang === 'uk') && VALID_WORDS.includes(cleanWord)) {
    return { valid: true, reason: 'local' };
  }

  // 3. Fallback to Dictionary API (Fast but remote)
  const apiLang = LANG_API_MAP[lang] || 'en';
  
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000); // 5s timeout
    
    const response = await fetch(`https://freedictionaryapi.com/api/v1/entries/${apiLang}/${cleanWord}`, {
      signal: controller.signal
    });
    
    clearTimeout(timeoutId);
    
    if (response.ok) {
      const data = await response.json();
      if (data.entries && data.entries.length > 0) {
        return { valid: true, reason: 'api' };
      }
    }
  } catch (error) {
    if (error.name === 'AbortError') {
      console.warn("Dictionary API lookup timed out");
    } else {
      console.error("Dictionary API Error:", error);
    }
  }

  return { valid: false, reason: 'invalid' };
}
